def solution(apt_str):
    lines = apt_str.strip().split('\n')
    n = len(lines)
    if n == 0:
        return apt_str

    m = len(lines[0])
    grid = []
    for line in lines:
        grid.append(list(line))

    # Directions for neighbors
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(start_r, start_c, visited):
        """BFS to find all connected free spaces"""
        queue = [(start_r, start_c)]
        visited[start_r][start_c] = True
        cells = [(start_r, start_c)]

        while queue:
            r, c = queue.pop(0)
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if not visited[nr][nc] and grid[nr][nc] == '.':
                        visited[nr][nc] = True
                        cells.append((nr, nc))
                        queue.append((nr, nc))

        return cells

    # Step 1: Collect all free space cells
    all_free = []
    visited = [[False] * m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                all_free.append((i, j))

    if not all_free:
        return '\n'.join(''.join(row) for row in grid)

    # Step 2: For all free cells, try to make them connect into rectangles
    # Strategy: Sort all free cells by row then column, and try to merge them
    # by removing necessary walls between them

    # Actually, the key insight: we want all free spaces to form rectangles
    # We can do this by checking which walls separate free spaces and removing them
    # if it helps create rectangles

    # Approach: Use a recursive approach where we expand each room as much as possible
    # by removing walls that are adjacent to existing free spaces

    # First, compute minimum enclosing rectangle for each connected component
    connected_components = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and not visited[i][j]:
                cells = bfs(i, j, visited)
                connected_components.append(cells)

    # For each connected component, find its bounding box
    # Then try to ensure all free cells within each bounding box become free

    for cells in connected_components:
        if not cells:
            continue

        rows = [r for r, c in cells]
        cols = [c for r, c in cells]
        min_r, max_r = min(rows), max(rows)
        min_c, max_c = min(cols), max(cols)

        # Mark all walls within this bounding box as free
        for i in range(min_r, max_r + 1):
            for j in range(min_c, max_c + 1):
                if grid[i][j] == '*':
                    grid[i][j] = '.'

    # Convert back to string
    result_lines = []
    for row in grid:
        result_lines.append(''.join(row))

    return '\n'.join(result_lines)

