    lines = input_str.strip().split('\n')
    idx = 0
    n = int(lines[idx])
    idx += 1

    ships = []
    for i in range(n):
        x, y = map(int, lines[idx].split())
        ships.append((float(x), float(y), i + 1))  # (x, y, original_index_in_ships)
        idx += 1

    bases = []
    for i in range(n):
        x, y = map(int, lines[idx].split())
        bases.append((float(x), float(y), i + 1))  # (x, y, original_index_in_bases)
        idx += 1

    def orientation(p: tuple, q: tuple, r: tuple) -> int:
        val = (q[0] - p[0]) * (r[1] - p[1]) - (q[1] - p[1]) * (r[0] - p[0])
        if abs(val) < 1e-9:
            return 0
        return 1 if val > 0 else 2

    def do_intersect(p1: tuple, q1: tuple, p2: tuple, q2: tuple) -> bool:
        o1 = orientation(p1, q1, p2)
        o2 = orientation(p1, q1, q2)
        o3 = orientation(p2, q2, p1)
        o4 = orientation(p2, q2, q1)

        if o1 != o2 and o3 != o4:
            return True
        return False

    # Matching: ships[i] -> base[matching[i]]
    matching = list(range(n))

    def has_intersection():
        for i in range(n):
            for j in range(i + 1, n):
                if do_intersect(ships[i][:2], bases[matching[i]], 
                              ships[j][:2], bases[matching[j]]):
                    return True
        return False

    import random

    # Try multiple random initial matchings to find one with minimal intersections
    best_matching = list(range(n))

    for _ in range(100):
        current = list(range(n))
        random.shuffle(current)
        matching = current

        def uncross(match, ships, bases):
            # Try to eliminate intersections
            changed = True
            for _ in range(n * n // 2):
                if not has_intersection():
                    break
                found = False
                for i in range(n):
                    for j in range(i + 1, n):
                        if do_intersect(ships[i][:2], bases[match[i]], 
                                      ships[j][:2], bases[match[j]]):
                            # Swap bases for these two ships
                            match[i], match[j] = match[j], match[i]
                            changed = True
                            found = True
                            break
                    if found:
                        break
                if not changed:
                    break
            return has_intersection()

        uncross(matching, ships, bases)

        if not has_intersection():
            return '\n'.join(str(m + 1) for m in matching)

    # Fallback to brute force iteration
    for _ in range(n * n):
        if not has_intersection():
            return '\n'.join(str(m + 1) for m in matching)

        found = False
        for i in range(n):
            for j in range(i + 1, n):
                if do_intersect(ships[i][:2], bases[matching[i]], 
                              ships[j][:2], bases[matching[j]]):
                    matching[i], matching[j] = matching[j], matching[i]
                    found = True
                    break
            if found:
                break

    return '\n'.join(str(m + 1) for m in matching)

