        remaining_count = bin(sum(1 for i in range(n) if not ((picked_mask >> i) & 1))).count('1')

        if action == 'p':
            if team == 1:
                # Team 1 picks highest available
                # Get the highest index that isn't used
                h = max(i for i in range(n) if not ((picked_mask >> i) & 1))
                val = sorted_strengths[h]

                return val + solve(idx + 1, picked_mask | (1 << h))
            else:
                # Team 2 picks highest available
                h = max(i for i in range(n) if not ((picked_mask >> i) & 1))
                val = sorted_strengths[h]

                return -(val) + solve(idx + 1, picked_mask | (1 << h))
        else:  # 'b'
            # Ban the highest available
            h = max(i for i in range(n) if not ((picked_mask >> i) & 1))
            return solve(idx + 1, picked_mask | (1 << h))

    return solve(0, 0)


