    for i in range(m):
        parts = lines[3 + i].split()
        actions.append((parts[0], int(parts[1])))

    sorted_strengths = sorted(strengths, reverse=True)

    @lru_cache(maxsize=None)
    def dp(action_idx, unused_mask):
        if action_idx == m:
            return 0

        action, team = actions[action_idx]

        # Find the highest available hero (largest index in unused_bitset is wrong!)
        # Actually we work with sorted_strengths indexed 0 to n-1
        # The "highest" means largest value, which is at the earliest valid unused index

        unused_indices = [i for i in range(n) if not ((unused_mask >> i) & 1)]

        if not unused_indices:
            return 0

        highest = unused_indices[0]  # First unused index (highest strength because sorted descending)

        if action == 'p':
            if team == 1:
                val = sorted_strengths[highest]
                return val + dp(action_idx + 1, unused_mask | (1 << highest))
            else:
                val = sorted_strengths[highest]
                return -val + dp(action_idx + 1, unused_mask | (1 << highest))
        else:  # 'b'
            return dp(action_idx + 1, unused_mask | (1 << highest))

    return dp(0, 0)

