        for i in range(len(seg_list)):
            for j in range(i + 1, len(seg_list)):
                u, v = seg_list[i], seg_list[j]
                adj[u] |= (1 << v)
                adj[v] |= (1 << u)

    max_mis = [0]
    full_mask = (1 << n_friends) - 1

    def dfs(rmask, cnt):
        if cnt + remaining_count(rmask) <= max_mis[0]:
            return
        if rmask == 0:
            max_mis[0] = max(max_mis[0], cnt)
            return

        idx = (rmask & -rmask).bit_length() - 1

        # Try not including idx
        dfs(rmask ^ (1 << idx), cnt)

        # Try including idx if no neighbor is also available
        if ((adj[idx] & (rmask ^ (1 << idx))) == 0):
            dfs(rmask ^ (1 << idx), cnt + 1)

    dfs(full_mask, 0)
    return str(max_mis[0])

