def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(2 * m + 1)]

    def add_implication(u, v):
        adj[u].append(v)

    def get_node(lit):
        # Returns node index for literal: 
        # For variable v: 2*v+1 represents x_v is true, 2*v represents x_v is false
        if lit > 0:
            return 2 * lit + 1
        else:
            return 2 * abs(lit)

    def get_neg_node(u):
        # Flip between true and false representations
        return u ^ 1

    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        k = parts[0]
        literals = parts[1:]

        # Handle k=1 (unit clause): literal must be true
        if len(literals) == 1:
            lit = literals[0]
            add_implication(get_node(lit), get_neg_node(get_node(lit)))
            # Add direct implication
            u = get_node(lit)
            add_implication(get_neg_node(u), u)
        else:
            # For k >= 2, binary clauses pairs
            for a in range(len(literals) - 1):
                for b in range(a + 1, len(literals)):
                    lit_a = literals[a]
                    lit_b = literals[b]
                    # For clause (a OR b): -a -> b AND -b -> a
                    na = get_neg_node(get_node(lit_a))
                    nb = get_neg_node(get_node(lit_b))
                    add_implication(na, get_node(lit_b))
                    add_implication(nb, get_node(lit_a))

    # Kosaraju's SCC algorithm
    visited = [False] * len(adj)
    order = []

    def dfs1(u):
        visited[u] = True
        for v in adj[u]:
            if not visited[v]:
                dfs1(v)
        order.append(u)

    for i in range(len(adj)):
        if not visited[i]:
            dfs1(i)

    visited = [False] * len(adj)
    scc = [-1] * len(adj)
    scc_cnt = [0]

    def dfs2(u, c):
        visited[u] = True
        scc[u] = c
        for v in reversed(adj[u]):
            if not visited[v]:
                dfs2(v, c)

    # Process in reverse topological order
    for i in range(len(order) - 1, -1, -1):
        u = order[i]
        if not visited[u]:
            dfs2(u, scc_cnt[0])
            scc_cnt[0] += 1

    # Check satisfiability
    for var in range(1, m + 1):
        node = get_node(var)
        neg_node = get_neg_node(node)
        if scc[node] == scc[neg_node]:
            return 'NO\n'

    # Determine assignment
    sb = []
    for var in range(1, m + 1):
        node = get_node(var)
        neg_node = get_neg_node(node)
        # Variable is true if negation comes first in topological order
        if scc[neg_node] > scc[node]:
            sb.append('1')
        else:
            sb.append('0')

    return 'YES\n' + ''.join(sb)

