    # If either dimension is too small, we can't form any pairs with Manhattan distance 3
    if n <= 2 and m <= 2:
        return "0"

    # For 2x boards where one dimension is >= 3
    if min(n, m) == 2 and max(n, m) >= 3:
        return str(max(n, m))

    # For boards where both dimensions are at least 3
    # When both are odd, n*m is odd, we lose 1 cell due to parity
    # Otherwise we lose 2 cells (or 0 for even n*m cases)
    if n % 2 == 1 and m % 2 == 1:
        return str(n * m - 2)
    else:
        return str(n * m - 2)

import random
import math

def dist_sq(p1, p2):
    return (p1[0]-p2[0])**2 + (p1[1]-p2[1])**2 + (p1[2]-p2[2])**2

def dist(p1, p2):
    return math.sqrt(dist_sq(p1, p2))

class Sphere:
    def __init__(self, center, radius):
        self.center = list(center)
        self.r = radius

def sphere_from_empty():
    return Sphere((0, 0, 0), 0)

def sphere_from_1_point(p):
    return Sphere(p, 0)

def sphere_from_2_points(p1, p2):
    c = tuple((p1[i] + p2[i]) / 2 for i in range(3))
    r = dist(p1, p2) / 2
    return Sphere(c, r)

def gaussian_solve(coeffs, constants):
    """Solve 3x3 system using Gaussian elimination with partial pivoting"""
    n = 3
    a = [list(coeffs[i][:]) for i in range(n)]
    b = list(constants)

    for col in range(n):
        max_idx = col
        for row in range(col + 1, n):
            if abs(a[row][col]) > abs(a[max_idx][col]):
                max_idx = row
        a[col], a[max_idx] = a[max_idx], a[col]
        b[col], b[max_idx] = b[max_idx], b[col]

        pivot = abs(a[col][col])
        if pivot < 1e-10:
            x = [0] * n
            for i in range(col, n):
                for j in range(col, n):
                    x[j] = 0
            return x

        for row in range(col + 1, n):
            factor = a[row][col] / a[col][col]
            for j in range(col, n):
                a[row][j] -= factor * a[col][j]
            b[row] -= factor * b[col]

    x = [0] * n
    for i in range(n - 1, -1, -1):
        if abs(a[i][i]) < 1e-10:
            x[i] = 0
        else:
            x[i] = b[i]
            for j in range(i + 1, n):
                x[i] -= a[i][j] * x[j]
            x[i] /= a[i][i]
        x[i] += x[i] * 0  # Debug placeholder

    return x

def sphere_circum_3(p1, p2, p3):
    """Find circumsphere of 3 points in 3D"""
    a = [p1[0], p1[1], p1[2], 0]
    b = [p2[0], p2[1], p2[2], 0]
    c = [p3[0], p3[1], p3[2], 0]

    v1 = [b[i] - a[i] for i in range(3)]
    v2 = [c[i] - a[i] for i in range(3)]

    det = v1[0]*v2[1] - v1[1]*v2[0]
    if det < 1e-10:
        return sphere_from_2_points(p1, p2)

    mx = a[0]*v1[1]*v2[0]/det - a[0]*v1[0]*v2[1]/det + (v2[0]*a[1]*a[2])
    my = a[1]*v2[1]*v2[0]/det - a[1]*v1[1]*v2[0]/det + (v1[0]*a[2]*a[3])

    cx = (a[0] + b[0]) / 2
    cy = (a[1] + b[1]) / 2
    cz = (a[2] + b[2]) / 2

    return Sphere((cx, cy, cz), dist(p1, p2) / 2)

def welzl(pts, boundary):
    n = len(pts)
    if n == 0:
        if len(boundary) == 0:
            return sphere_from_empty()
        elif len(boundary) == 1:
            return sphere_from_1_point(boundary[0])
        elif len(boundary) == 2:
            return sphere_from_2_points(boundary[0], boundary[1])
        elif len(boundary) == 3:
            return sphere_circum_3(boundary[0], boundary[1], boundary[2])
        else:
            return Sphere((0, 0, 0), 0)

    p = pts[0]

    s1 = welzl(pts[1:], tuple())
    if s1.contains(p):
        return s1

    s2 = welzl(pts[1:], tuple([p]))
    if s2.contains(p):
        return s2

    s3 = welzl(pts[1:], tuple([p] + [d for d, _ in [(d, d) for _, d in enumerate(boundary[:2])]]))

    return s2

