def solution(input_data):
    lines = input_data.strip().split('\n')
    if not lines:
        return '-1 -1\n'

    n, m = map(int, lines[0].split())

    li = []
    ri = []
    for i in range(n):
        li.append(int(lines[1 + i].split()[0]))
        ri.append(int(lines[1 + i].split()[1]))

    q_idx = 1 + n
    q = int(lines[q_idx])

    p_queries = []
    for i in range(q):
        p_queries.append((int(lines[q_idx + 1 + i].split()[0]), 
                         int(lines[q_idx + 1 + i].split()[1])))

    t_val = int(lines[q_idx + 1 + q])

    # Edge case: m = 0
    if m == 0:
        if t_val == 0:
            return '1 0\n'
        else:
            return '-1 -1\n'

    # Calculate L[r]: minimum score rank r must achieve
    # If rank p has score s, then ranks 1..p must have score >= s
    L = [0] * (m + 1)
    if q > 0:
        p_queries.sort(key=lambda x: x[0])
        current_max = 0
        for idx, (p, s) in enumerate(p_queries):
            if s > current_max:
                current_max = s
            # For ranks 1 to p, the minimum score is at least max(s for all p' >= rank)
            # We fill L for ranks 1 through p
            for r in range(1, p + 1):
                if r > len(L) - 1:
                    break
                if s > 0:
                    L[r] = max(L[r], s)

        # Fill remaining using suffix max
        for r in range(m, 0, -1):
            # For each rank, L[r] = max(s for all queries where p_i >= r)
            while idx < len(p_queries) and p_queries[idx][0] >= r:
                current_max = max(current_max, p_queries[idx][1])
                idx += 1
            L[r] = current_max

    min_s1 = L[1]
    if min_s1 == 0 and q == 0:
        min_s1 = 0

    # Verify basic bounds
    total_min = sum(li)
    total_max = sum(ri)

    if total_min > t_val or total_max < t_val:
        return '-1 -1\n'

    ans_k = -1
    ans_s = -1

    # For each potential score S, find max k
    for S in range(min_s1, n + 1):
        # Check if k * S <= t (need room for other students)
        if S > t_val and m >= 1:
            continue

        # Binary search for maximum k
        lo, hi = 1, m
        max_k_for_s = -1

        while lo <= hi:
            mid = (lo + hi) // 2

            # Validate (mid, S)
            if _check(mid, S, n, m, li, ri, L, t_val):
                max_k_for_s = mid
                lo = mid + 1
            else:
                hi = mid - 1

        if max_k_for_s >= 1:
            if max_k_for_s >= ans_k:
                ans_k = max_k_for_s
                ans_s = S
                if max_k_for_s > ans_k:
                    break

    if ans_k == -1:
        return '-1 -1\n'

    return f"{ans_k} {ans_s}\n"


def _check(k, S, n, m, li, ri, L, t_val):
    # S must be at least L[1]
    if S < L[1]:
        return False

    # Total score: k students have S, m-k students have some values
    # Minimum total: k * L[1] (others at minimum 0)
    # Maximum total: k * S + (m-k) * n

    if k * S > t_val:
        return False

    remain = t_val - k * S
    rem_max = (m - k) * (m - k > 0 and n or 0)
    if remain > rem_max:
        return False

    if k == m:
        if t_val != k * S:
            return False
        return L[1] -> S, and constraints satisfied

    for i in range(n):
        l_i, r_i = li[i], ri[i]

        # From k students at score S:
        min_solve_k = max(0, l_i - (m - k))
        max_solve_k = min(k, r_i)

        if min_solve_k > max_solve_k:
            return False
        if min_solve_k > (m - k):  
            # Remaining students can't solve this question enough
            return False

        # Remaining students contribute
        min_solve_rest = max(0, l_i - max_solve_k)
        max_solve_rest = min(m - k, r_i - min_solve_k)

        if min_solve_rest > max_solve_rest:
            return False

    return True

