                   grid[(i + 1) % 2][(j + 1) % 2] if grid[(i + 1) % 2][(j + 1) % 2] != '0' else None)]

        # Use a fixed pattern: (i%2 == 0, j%2 == 0) -> 1, (i%2 == 0, j%2 == 1) -> 2
        #                    (i%2 == 1, j%2 == 0) -> 3, (i%2 == 1, j%2 == 1) -> 4
        if i % 2 == 0 and j % 2 == 0:
            return 1
        elif i % 2 == 0 and j % 2 == 1:
            return 2
        elif i % 2 == 1 and j % 2 == 0:
            return 3
        else:
            return 4

    # Generate colors for empty cells and verify all connections
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '0':
                grid[i][j] = str(get_color(i, j))

    # Double check connections
