                            continue
                        c2 = int(grid[ni][nj])
                        if c1 == c2:
                            valid = False
                            break
                if not valid:
                    break
            if not valid:
                break
        if not valid:
            break

    if valid:
        return '\n'.join(''.join(row) for row in grid)
    else:
        return "0"

