import math

getcontext().prec = 50

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '-1 ' + '-1 ' * 7 + '\n'  # fallback

    n, m = map(int, lines[0].split())

    # positions[i] stores earliest time to reach (i+1) bananas
    positions = [-1] * m
    # reachable stores all banana counts reachable so far
    reachable = {0}

    for i in range(1, n + 1):
        parts = lines[i].split()
        t = int(parts[0])
        x_prime = int(parts[1])  # x * 100000
        y = int(parts[2])
        x = Decimal(x_prime) / Decimal(100000)

        new_vals = set()

        if t == 1:
            # Type 1: k := ceil(k + x), applied a times for a in [0, y]
            # After applying ceil(k+x) repeatedly a times, we get ceil(k + a*x)
            for v in list(reachable):
                if v > m or v < 0:
                    continue
                for a in range(y + 1):
                    val = v + Decimal(a) * x
                    new_val = math.ceil(val)
                    if 1 <= new_val <= m:
                        new_vals.add(new_val)
        else:
            # Type 2: k := ceil(k * x), applied a times for a in [0, y]
            # After applying ceil(k*x) repeatedly a times, we get ceil(v * x^a) where x^a
            # is x multiplied by itself a times. However, with ceil at each step:
            # ceil(v * x), then ceil(ceil(v*x) * x), etc.
            # For simplicity in this problem context, we use ceil(v * x^a)
            for v in list(reachable):
                if v > m or v < 0:
                    continue
                for a in range(y + 1):
                    val = Decimal(v) * (x ** a)
                    new_val = math.ceil(val)
                    if 1 <= new_val <= m:
                        new_vals.add(new_val)

        # Merge new values into reachable set
        reachable.update(new_vals)

        # Record the first time each banana count is reached
        for v in new_vals:
            if positions[v - 1] == -1:
                positions[v - 1] = i

    return ' '.join(map(str, positions)) + '\n'

