def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    e = list(map(int, lines[2].split()))

    if n == 0:
        return "0\n"

    # Check if any a_i is already 1 (or we can reach 1 directly)
    if any(x == 1 for x in a):
        return "0\n"

    # For each judge, find all achievable values after division
    # achievable[i] = {a_i / d : d divides a_i, d <= k}
    achievable = []
    for x in a:
        achievable.insert(0, [])
        divs = []
        d = 1
        while d * d <= x:
            if x % d == 0:
                if d <= k:
                    divs.append(d)  # a_i/d is a divisor, same result
                if d * d != x and (x // d) <= k:
                    divs.append(x // d)
            d += 1
        achievable[-1] = sorted(set(divs))

    # BFS to find minimum cost path to GCD = 1
    # State: current GCD value
    # dp[g] = minimum cost to reach GCD state g

    dp = {}
    dp[a[0]] = float('inf')  # Initial state: first element

    # Actually we need to track which state each number contributes
    # Better: start with each element individually and build up

    best = float('inf')

    # Initialize: each judge individually
    for i in range(n):
        for v in achievable[i]:
            if v == 1:
                best = min(best, e[i])

    # If we already found 0 cost (a_i = 1), return it
    if best == 0:
        return "0\n"

    # BFS where state is (GCD value)
    # Transitions: add next judge's contribution

    from collections import deque
    queue = deque([[a[0], 0]])  # (current_gcd, cost)
    visited = {}  # gcd -> min_cost

    while queue:
        g, cost = queue.popleft()

        if g == 1:
            best = min(best, cost)
            continue

        if g in visited and visited[g] <= cost:
            continue
        visited[g] = cost

        # Try each remaining judge
        for i in range(n):
            for v in achievable[i]:
                new_g = math.gcd(g, v)
                new_cost = cost + e[i]

                if new_g not in visited or visited[new_g] > new_cost:
                    if new_g not in visited:
                        queue.append([new_g, new_cost])
                    visited[new_g] = new_cost

    return f"{best if best < float('inf') else -1}\n"

