            if g == 1:
                min_cost = min(min_cost, cost)
                continue

            if seen.get((g, end_idx), float('inf')) <= cost:
                continue

            # Try next judges
            for i in range(end_idx + 1, n):
                for v in achievable[i]:
                    new_g = math.gcd(g, v)
                    new_cost = cost + e[i]

                    if new_g == 1:
                        min_cost = min(min_cost, new_cost)
                        continue

                    if new_cost < seen.get((new_g, i), float('inf')):
