def is_diagonal_square(matrix, r, c, size):
    # Check the 4 corner points of the square
    p1 = matrix[r][c]
    p2 = matrix[r][c + size - 1]
    p3 = matrix[r + size - 1][c]
    p4 = matrix[r + size - 1][c + size - 1]

    if p1 != '1' or p2 != '1' or p3 != '1' or p4 != '1':
        return False

    # Check top edge: diagonal from (r, c) to (r+size-1, c+size-1)
    for i in range(size):
        if matrix[r + i][c + i] != '1':
            return False

    # Check right edge: vertical line at column c+size-1
    for i in range(size):
        if matrix[r + i][c + size - 1] != '1':
