        for v in adj[u]:
            if v == p:
                continue

            dfs(v, u)

            child_dp = dp[v]
            merged_dp = {}

            # Combine child's components with current component
            for s, val in dp[u].items():
                for j, cval in child_dp.items():
                    new_s = s + j
