            max_child_prod = max(child_dp.values())
            for s, val in dp[u].items():
                merged_dp[s] = max(merged_dp.get(s, 0), val * max_child_prod)

            dp[u] = merged_dp

    dfs(1)

    # The answer is the maximum product for the root's subtree
    ans = max(dp[1].values()) if dp[1] else 1
