        end = min(a_max, b_max)
        if start >= end:
            return None
        return (start, end)

    sol_min, sol_max = 0.0, 1000.0

    for rix, riy, vix, viy in mice:
        x_min, x_max = None, None
        y_min, y_max = None, None

