def solution(s):
    n, m = map(int, s.strip().split())
    MOD = 998244853

    # dp[i][j][imb] stores the count of paths with i ones, j minus ones,
    # and current imbalance i - j, where 0 <= i <= n and 0 <= j <= m
    # Use dictionary for sparse storage
    dp = {}

    dp[(0, 0, 0)] = 1

    # Also track maximum prefix sum for each (i, j, imb) state
    max_sum = {}
    max_sum[(0, 0, 0)] = 0

    for i in range(n + 1):
        for j in range(m + 1):
            for imb in range(-(j - i), i - j + 1):
                if (i, j, imb) in dp:
                    current_max = max_sum.get((i, j, imb), -float('inf'))
                    # Try adding a 1:
                    if i < n:
                        new_imb = imb + 1
                        current_new_max = max(current_max, new_imb)
                        new_key = (i + 1, j, new_imb)
                        dp[new_key] = (dp[new_key] + dp[(i, j, imb)]) % MOD
                        max_sum[new_key] = max(max_sum.get(new_key, -float('inf')), current_new_max)

                    # Try adding a -1:
                    if j < m:
                        new_imb = imb - 1
                        current_new_max = max(current_max, new_imb)
                        new_key = (i, j + 1, new_imb)
                        dp[new_key] = (dp[new_key] + dp[(i, j, imb)]) % MOD
                        max_sum[new_key] = max(max_sum.get(new_key, -float('inf')), current_new_max)

    result = 0
    for (i, j, imb), count in dp.items():
        if i == n and j == m:
            for max_val, ways in max_sum.items():
                # Only count if this max_val was achieved
                if ways == imb:
                    result = (result + max_val * ways) % MOD

    return str(result)

def get_prime_factors(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            cnt = 0
            while temp % d == 0:
                cnt += 1
                temp //= d
            factors[d] = cnt
        d += 1
    if temp > 1:
        factors[temp] = 1
    return factors

