        return "1\n" + " ".join(str(i) for i in range(1, m+1)) + "\n"

    conn = []
    for line in strings:
        parts = line.split()
        s1, p1, s2, p2 = parts[0], int(parts[1]), parts[2], int(parts[3])

        if s1 == s2 or p1 == 0 or p2 == 0 or p1 > n or p2 > m:
            return "No solution\n"

        conn.append((s1, p1, s2, p2))

    # This problem requires checking planar embedding conditions
    # The core check is whether string dependencies form a valid outerplanar graph

    # For a working solution, we check:
    # 1. No two strings share identical pins
    # 2. The dependency graph is planar (tree-like structure)
    # 3. Can be embedded without crossings

    # Build pin graph
    graph = {}
    for (s1, p1, s2, p2) in conn:
        if s1 == 'L':
            graph[(s1, p1)] = graph.get((s1, p1), []) + [(s2, p2)]
        if s2 == 'L':
            graph[(s1, p1)] = graph.get((s1, p1), []) + [(s2, p2)]

    # Simple check: if graph has cycles or high degree, no solution
    visited = set()

    def dfs(node, parent, depth):
        node = node if isinstance(node, tuple) else ('L', node) if node in graph else None
        if node not in graph:
            return False
        if node[0] == node[1]:
            return False  # Same side peers
        for neighbor in graph[node]:
            neighbor = neighbor if isinstance(neighbor, tuple) else ('L', neighbor) if neighbor in graph else None
            if neighbor and neighbor not in visited:
                if dfs(neighbor, node, depth + 1):
