def solution(input_str):
    input_str = input_str.strip()
    if not input_str:
        return '0\n'

    parts = input_str.split()
    x = int(parts[0])
    y = int(parts[1])

    if y == 0:
        return '0\n'

    # The key insight is that f(a, b) follows the Euclidean algorithm pattern
    # f(a, b) = b // a + f(a, b % a) when b >= a
    # f(a, b) = 1 when b < a (but b > 0)
    # f(a, b) = b when a == 1

    memo = {}

    def f(a, b):
        if b == 0:
            return 0
        if b < a:
            return 1
        if a == 1:
            return b

        if (a, b) in memo:
            return memo[(a, b)]

        key = (a, b)
        result = b // a + f(a, b % a)
        memo[key] = result

        return result

    result = f(x, y)
    return f"{result}\n"

