        parts = lines[idx].split()
        idx += 1
        u = int(parts[0]) - 1
        v = int(parts[1]) - 1
        adj[u].append(v)

    # Compute all-pairs shortest paths using BFS from each node
    INF = float('inf')
    dists = [[INF] * n for _ in range(n)]

    for start in range(n):
        dists[start][start] = 0
        q = collections.deque([start])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dists[start][v] == INF:
                    dists[start][v] = dists[start][u] + 1
                    q.append(v)

    # Precompute top 2 incoming paths to each city (from cities != j)
    top_in = [[] for _ in range(n)]
    for j in range(n):
        candidates = []
        for i in range(n):
            if i != j and dists[i][j] < INF:
                candidates.append((i, dists[i][j]))
        candidates.sort(key=lambda x: x[1], reverse=True)
        top_in[j] = candidates[:2]  # Top 2 (in case first is not useful)

    # Precompute top 2 outgoing paths from each city (to cities != k)
    top_out = [[] for _ in range(n)]
    for k in range(n):
        candidates = []
        for l in range(n):
            if l != k and dists[k][l] < INF:
                candidates.append((l, dists[k][l]))
        candidates.sort(key=lambda x: x[1], reverse=True)
        top_out[k] = candidates[:2]

    best_i, best_j, best_k, best_l = -1, -1, -1, -1
    best_dist = -1

    # Try all pairs of middle cities (j, k)
    for j in range(n):
        for k in range(n):
            if j == k:
                continue

            # Middle distance
            d_jk = dists[j][k]
            if d_jk == INF:
                continue

            # Try first best incoming to j from i
            use_in1 = True
            if top_in[j]:
                for i, d_i_j in top_in[j]:
                    if i != j and i != k:
                        break
                else:
                    use_in1 = False
            else:
                use_in1 = False

            if use_in1:
                i, d_i_j = top_in[j][0]
            else:
                # Try second best
                if len(top_in[j]) < 2:
                    continue
                i, d_i_j = top_in[j][1]
                if i == j or i == k:
                    continue

            # Try first best outgoing from k to l
            use_out1 = True
            if top_out[k]:
                for l, d_k_l in top_out[k]:
                    if l != i and l != j and l != k:
                        break
                else:
                    use_out1 = False
            else:
                use_out1 = False

            if use_out1:
                l, d_k_l = top_out[k][0]
            else:
                # Try second best
                if len(top_out[k]) < 2:
                    continue
                l, d_k_l = top_out[k][1]
                if l == i or l == j or l == k:
                    continue

            # Valid 4-city tour found
            total = d_i_j + d_jk + d_k_l
            if total > best_dist:
                best_dist = total
                best_i, best_j, best_k, best_l = i, j, k, l

    if best_i == -1:
        return ""

    return f"{best_i + 1} {best_j + 1} {best_k + 1} {best_l + 1}"

