        """Compute triangle area using cross product formula"""
        return abs((b[0] - a[0]) * (c[1] - a[1]) - 
                   (c[0] - a[0]) * (b[1] - a[1])) / 2.0

    max_radius = 0.0
    found_valid = False

    for i in range(n):
        for j in range(i + 1, n):
