    dp[0][offset] = (None, None)

    for i in range(n):
        for d in range(num_diffs):
            if dp[i][d] == (None, None):
                continue

            curr_diff = d - offset
            char_given = s[i]
            options = []

            if char_given == '?':
                options = ['W', 'L', 'D']
            elif char_given == 'W':
                options = ['W']
            elif char_given == 'L':
                options = ['L']
            else:
                options = ['D']

            for m in options:
                if m == 'W':
                    next_diff = curr_diff + 1
                elif m == 'L':
                    next_diff = curr_diff - 1
                else:
                    next_diff = curr_diff

                # Check if transition is valid
                if abs(next_diff) == k:
                    # Can only reach |diff| = k at the final position
                    if i == n - 1:
                        new_d = next_diff + offset
                        if dp[i + 1][new_d] == (None, None):
                            dp[i + 1][new_d] = (d, m)
                else:
                    # For intermediate positions, |diff| must be < k
                    if abs(next_diff) < k:
                        new_d = next_diff + offset
                        if dp[i + 1][new_d] == (None, None):
                            dp[i + 1][new_d] = (d, m)

    # Find any valid final state (position n with |diff| == k)
    for d in range(num_diffs):
        if abs(d - offset) == k and dp[n][d] != (None, None):
            # Reconstruct the sequence
            result = []
            curr_d = d
            for i in range(n):
                prev_d, m = dp[i + 1][curr_d]
                result.append(m)
                curr_d = prev_d

            return ''.join(reversed(result))

    return "NO"

