def get_prime_factors(n):
    factors = set()
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.add(d)
            n //= d
        d += 1
    if n > 1:
        factors.add(n)
    return factors

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    arr = list(map(int, lines[1].split()))

    if len(arr) == 0:
        return "0"

    candidates = set()
    for x in arr:
        candidates.update(get_prime_factors(x))

    if not candidates:
        # Default: we can change all elements to be divisible by any prime
        # First element can be made divisible with cost 0*n
        ans = 0
    else:
        # Set upper bound: change all elements
        ans = n * b

    # Try each candidate prime
    for p in candidates:
        type_arr = []
        for x in arr:
            rem = x % p
            if rem == 0:
                type_arr.append(0)
            elif rem == 1 or rem == p - 1:
                type_arr.append(1)
            else:
                type_arr.append(2)

        type1_count = type_arr.count(1)
        type2_min = type2_max = -1
        has_type2 = False

        for i, t in enumerate(type_arr):
            if t == 2:
                if not has_type2:
                    type2_min = type2_max = i
                    has_type2 = True
                else:
                    type2_max = max(type2_max, i)

        # Cost without deletion
        cost_no_delete = type1_count * b
        ans = min(ans, cost_no_delete)

        # Cost with deletion (covers all type2 elements)
        if has_type2:
            delete_len = type2_max - type2_min + 1
            type1_in_delete = 0
            for i in range(type2_min, type2_max + 1):
                if type_arr[i] == 1:
                    type1_in_delete += 1

            type1_outside = type1_count - type1_in_delete
            cost_with_delete = a * delete_len + type1_outside * b
            ans = min(ans, cost_with_delete)

    return str(ans)

