from collections import Counter

def solution(data):
    lines = data.strip().split('\n')
    shuffled = lines[0]
    substring = lines[1]

    total_len = len(shuffled)
    best_result = None

    for d in range(1, total_len - len(str(total_len - 1)) + 2):
        k_str = str(d)
        if d + len(k_str) != total_len:
            continue

        shuffled_count = Counter(shuffled)
        k_count = Counter(k_str)

        if any(k_count[c] > shuffled_count[c] for c in k_count):
            continue

        remaining = []
        remaining_copy = shuffled.copy()
        k_remaining_copy = k_count.copy()

        for _ in range(d):
            placed = False
            for c in k_remaining_copy:
                if k_remaining_copy.get(c, 0) > 0 and c in remaining_copy:
                    remaining.append(c)
                    remaining_copy.remove(c)
                    k_remaining_copy[c] -= 1
                    placed = True
                    break
            if not placed:
                break

        if len(remaining) != d:
            continue

        for i in range(d + 1):
            cand = remaining[:i] + substring + remaining[i:]
            if len(cand) == d and substring in cand:
                # Validate: cand should have only d characters
                if set(cand).issubset(set(map(str, range(10)))) and len(cand) == d:
                    if best_result is None or int(cand or '0') < int(best_result or '0'):
                        best_result = cand

    if best_result is None and total_len > 0:
        best_result = ''.join(sorted(shuffled))

    return best_result if best_result else "0"


