from collections import Counter

def solution(data):
    def solve():
        lines = data.strip().split('\n')
        shuffled = lines[0]
        substring = lines[1]

        total = len(shuffled)
        best = None

        for d in range(1, total + 1):
            k_str = str(d)
            needed = d + len(k_str)  # digits needed: d for n, len(str(d)) for k

            if needed != total:
                continue

            count = Counter(shuffled)
            k_count = Counter(k_str)

            # Check if we have enough for k
            for c, v in k_count.items():
                if count[c] < v:
                    break
            else:
                # Build remaining digits after removing k
                rem = []
                for c in shuffled:
                    count[c] -= 1
                    if count[c] >= 0:
                        rem.append(c)

                if len(rem) != d:
                    continue

                # Build candidate with substring - simplest is just sorted
                rem.sort()

                # Try all valid insertions of substring into rem (rem should already contain it)
                for i in range(d + 1):
                    cand = rem[:i] + substring + rem[i:]
                    if len(cand) == d and substring in cand:
                        if best is None or int(cand if cand else '0') < int(best if best else '0'):
                            best = cand

                # Stop processing for this d
                break
            count.clear()

        return str(best) if best else "0"

    return solve()


