            # Maximum on clockwise arc (positions i+1 to j-1)
            if i + 1 < j:
                clockwise_max = max(h[i+1:j])
            else:
                clockwise_max = 0  # No hills between i and j clockwise

            # Maximum on counter-clockwise arc (positions j+1 to n-1, then 0 to i-1)
            if j + 1 < n:
                tail = h[j+1:]
            else:
                tail = []
            if i >= 1:
                head = h[:i]
            else:
                head = []
            counter_max = max(tail + head) if (tail or head) else 0

            # Can see each other if at least one arc has max <= min(hills[i], hills[j])
            if clockwise_max <= min(h[i], h[j]) or counter_max <= min(h[i], h[j]):
                ans += 1

    return f"{ans}\n"

