def solution(input_str):
    MOD = 1000000007

    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Track variable occurrences
    var_clauses = {}  # var_id -> list of clause indices
    clause_vars = []  # clause i -> list of variables

    for i in range(n):
        parts = lines[1 + i].split()
        k = int(parts[0])
        clause_vars.append([int(parts[j+1]) for j in range(k)])

    # Count variable occurrences
    for i in range(n):
        for lit in clause_vars[i]:
            var_id = abs(lit)
            if var_id not in var_clauses:
                var_clauses[var_id] = []
            var_clauses[var_id].append(i)

    # Variables appearing in no clauses contribute factor of 2 each
    ans = 1
    counted_vars = set()
    for v in range(1, m + 1):
        if v not in var_clauses:
            ans = (ans * 2) % MOD
        else:
            counted_vars.add(v)

    # Build graph and process each component
    # Union-Find for components
    parent = list(range(m + 1))
    rank = [0] * (m + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return px
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
        return px

def solution(input_str: str) -> str:
    """
    Solve the pollywogs energy optimization problem.

    Key insight: The pollywogs always occupy x consecutive stones,
    and only the leftmost pollywog moves. We can track just the
    position of the leftmost pollywog.

    Steps:
    1. Parse input
    2. Identify all important positions (start, target, special stones)
    3. Fill in intermediate positions reachable within jump distance k
    4. Use dynamic programming to find minimum cost
    5. Add special stone energy costs
    """
    lines = input_str.strip().split('\n')
    lines = [l for l in lines if l.strip()]

    if len(lines) < 2:
        return "0\n"

    x, k, n, q = map(int, lines[0].split())
    c = list(map(int, lines[1].split()))

    special = {}
    for i in range(q):
        p, wp = map(int, lines[2 + i].split())
        special[int(p)] = int(wp)

    target = n - x + 1
    INF = float('inf')

    if target < 1:
        return "0\n"

    # Collect all important positions: 1, target, and special stones
    all_pos = {1, target}
    for p in special:
        if 1 <= p <= target:
            all_pos.add(p)

    # Expand to include all positions reachable within jump distance k
    while True:
        added = False
        new_pos = set()
        for p in list(all_pos):
            for d in range(1, min(k + 1, target - p + 1)):
                np = p + d
                if 1 <= np <= target and np not in all_pos:
                    new_pos.add(np)
                    added = True
        if new_pos:
            all_pos.update(new_pos)
        else:
            break

    sorted_pos = sorted(all_pos)

    # DP to find minimum cost
    dp = {}
    dp[1] = 0

    for pos in sorted_pos:
        if pos == 1:
            continue
        min_cost = INF

        for d in range(1, k + 1):
            prev = pos - d
            if prev in dp and dp[prev] != INF:
                # Jump from prev to pos (distance d)
                jump_cost = dp[prev] + c[d - 1]
                # Add special stone cost if jumping to special stone
                if pos in special:
                    jump_cost += special[pos]
                if jump_cost < min_cost:
                    min_cost = jump_cost

        if min_cost != INF:
            dp[pos] = min_cost

    result = dp.get(target, INF)
    return str(int(result) if result != INF else "-1") + '\n'
